#include "ksPanelTextTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <utility>
int main(){using T=ks::PanelTextTask;using K=T::Kind;using S=T::Stage;using C=T::Child;unsigned cases=0;auto verify=[&](unsigned kind,unsigned input,unsigned length,unsigned memoryClock,uint32_t origin){T t(static_cast<K>(kind));std::vector<std::pair<C,unsigned>>events;unsigned used=0,inputReads=0,pointerReads=0,byteReads=0;auto clock=[&]{return memoryClock;};while(t.stage()!=S::Complete){auto child=t.child();if(child!=C::None){unsigned arg=child==C::Command?t.command():child==C::Parse||kind!=0?t.byte():t.input();if(child==C::ClearFirst||child==C::ClearSecond)arg=0;events.emplace_back(child,arg);t.resumeChild();continue;}auto cost=t.nextClocks(clock);if(t.advanceBefore(cost-1,[](T::Read){return 0;},clock))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](T::Read r)->uint32_t{if(r==T::Read::Input){++inputReads;return input;}if(r==T::Read::Pointer){++pointerReads;return origin;}if(t.pointer()!=uint32_t(origin+byteReads))throw std::runtime_error("source address/cursor");return byteReads++<length?input:0;},clock);}std::vector<std::pair<C,unsigned>>expected;unsigned clocks=0;if(kind==0){if(input<128){expected={{C::Write,input}};clocks=43;}else if(input==255){expected={{C::ClearSecond,0},{C::ClearFirst,0}};clocks=59;}else if(input==254){expected={{C::ClearFirst,0}};clocks=50;}else if(input==253){expected={{C::ClearSecond,0}};clocks=56;}else if(input==252){expected={{C::Command,14}};clocks=70;}else if(input==251){expected={{C::Command,12}};clocks=76;}else{expected={{C::Command,input}};clocks=73;}if(inputReads!=1||pointerReads||byteReads)throw std::runtime_error("parse input reads");}else{unsigned chars=input?length:0,reads=chars+1;for(unsigned i=0;i<chars;++i)expected.emplace_back(kind==1?C::Parse:C::Write,input);clocks=(kind==1?60:39)+(8+memoryClock)*reads+(kind==1?18:23)*chars;if(pointerReads!=1||inputReads||byteReads!=reads||t.pointer()!=uint32_t(origin+reads))throw std::runtime_error("string source/zero terminator/cursor");}if(events!=expected||used!=clocks)throw std::runtime_error("text command routing/order/clocks");++cases;};for(unsigned memoryClock:{1u,3u}){for(unsigned input=0;input<256;++input)verify(0,input,0,memoryClock,0);for(unsigned kind=1;kind<3;++kind)for(unsigned input=0;input<256;++input)for(unsigned length=0;length<9;++length)for(uint32_t origin:{0x30000u,0xfffffffeu})verify(kind,input,length,memoryClock,origin);}std::cout<<"PASS: "<<cases<<" pure panel-text properties\n";}
